     1	import { App, setIcon } from "obsidian";
     2	import type { ReactElement } from "react";
     3	import { SearchDropdown } from "~/components/SearchDropdown";
     4	import { activateOnKey } from "~/utils/keyboardHints";
     5	import {
     6	  SORT_OPTIONS,
     7	  getDefaultDirectionForKey,
     8	  getSortDirectionLabel,
     9	  getSortOptionLabel,
    10	  isDefaultSort,
    11	  type SortDirection,
    12	  type SortKey,
    13	} from "~/utils/discourseNodeSort";
    14	
    15	const DIRECTIONS: { direction: SortDirection; label: string }[] = [
    16	  { direction: "asc", label: "Asc" },
    17	  { direction: "desc", label: "Desc" },
    18	];
    19	
    20	const getDirectionIconName = (direction: SortDirection): string =>
    21	  direction === "asc" ? "arrow-up-narrow-wide" : "arrow-down-wide-narrow";
    22	
    23	/** Rows are divs, not buttons: Obsidian's button chrome reads as separate widgets rather than a menu. */
    24	const SortOptionRow = ({
    25	  isSelected,
    26	  label,
    27	  onSelect,
    28	}: {
    29	  isSelected: boolean;
    30	  label: string;
    31	  onSelect: () => void;
    32	}): ReactElement => (
    33	  <div
    34	    role="menuitemradio"
    35	    aria-checked={isSelected}
    36	    tabIndex={0}
    37	    onClick={onSelect}
    38	    onKeyDown={(event) => activateOnKey(event, onSelect)}
    39	    onMouseDown={(event) => event.preventDefault()}
    40	    className={`flex cursor-pointer items-center gap-2 px-3 py-1.5 text-sm ${
    41	      isSelected
    42	        ? "bg-accent text-on-accent"
    43	        : "text-normal hover:bg-modifier-hover"
    44	    }`}
    45	  >
    46	    {/* Always occupies its slot, so selecting an option does not shift the labels. */}
    47	    <span className="flex w-4 shrink-0 justify-center">
    48	      {isSelected && (
    49	        <span ref={(el) => (el && setIcon(el, "check")) || undefined} />
    50	      )}
    51	    </span>
    52	    <span className="truncate">{label}</span>
    53	  </div>
    54	);
    55	
    56	const DirectionToggle = ({
    57	  onSelect,
    58	  sortDirection,
    59	  sortKey,
    60	}: {
    61	  onSelect: (direction: SortDirection) => void;
    62	  sortDirection: SortDirection;
    63	  sortKey: SortKey;
    64	}): ReactElement => (
    65	  <div className="border-modifier-border flex gap-1 border-t p-2">
    66	    {DIRECTIONS.map(({ direction, label }) => (
    67	      <div
    68	        key={direction}
    69	        role="button"
    70	        aria-pressed={direction === sortDirection}
    71	        tabIndex={0}
    72	        title={getSortDirectionLabel({ sortKey, direction })}
    73	        onClick={() => onSelect(direction)}
    74	        onKeyDown={(event) => activateOnKey(event, () => onSelect(direction))}
    75	        onMouseDown={(event) => event.preventDefault()}
    76	        className={`flex flex-1 cursor-pointer items-center justify-center gap-1 rounded px-2 py-1 text-sm ${
    77	          direction === sortDirection
    78	            ? "bg-accent text-on-accent"
    79	            : "text-normal hover:bg-modifier-hover"
    80	        }`}
    81	      >
    82	        <span
    83	          className="flex items-center"
    84	          ref={(el) =>
    85	            (el && setIcon(el, getDirectionIconName(direction))) || undefined
    86	          }
    87	        />
    88	        {label}
    89	      </div>
    90	    ))}
    91	  </div>
    92	);
    93	
    94	export const NodeSortMenu = ({
    95	  app,
    96	  isOpen,
    97	  onOpenChange,
    98	  onSortChange,
    99	  sortDirection,
   100	  sortKey,
   101	}: {
   102	  app: App;
   103	  isOpen: boolean;
   104	  onOpenChange: (isOpen: boolean) => void;
   105	  onSortChange: (next: { sortKey: SortKey; direction: SortDirection }) => void;
   106	  sortDirection: SortDirection;
   107	  sortKey: SortKey;
   108	}): ReactElement => {
   109	  const directionLabel = getSortDirectionLabel({
   110	    sortKey,
   111	    direction: sortDirection,
   112	  });
   113	
   114	  return (
   115	    <SearchDropdown
   116	      app={app}
   117	      ariaLabel={`Sort by ${getSortOptionLabel(sortKey)}, ${directionLabel}`}
   118	      iconName={getDirectionIconName(sortDirection)}
   119	      isActive={!isDefaultSort({ sortKey, direction: sortDirection })}
   120	      isOpen={isOpen}
   121	      onOpenChange={onOpenChange}
   122	      panelClassName="w-56"
   123	      title={`Sort by ${getSortOptionLabel(sortKey)} — ${directionLabel}`}
   124	    >
   125	      <div role="group" className="pb-1">
   126	        <div className="text-muted px-3 pb-1 pt-2 text-xs">Sort by</div>
   127	        {SORT_OPTIONS.map((option) => (
   128	          <SortOptionRow
   129	            key={option.key}
   130	            isSelected={option.key === sortKey}
   131	            label={option.label}
   132	            onSelect={() =>
   133	              onSortChange({
   134	                sortKey: option.key,
   135	                direction:
   136	                  option.key === sortKey
   137	                    ? sortDirection
   138	                    : getDefaultDirectionForKey(option.key),
   139	              })
   140	            }
   141	          />
   142	        ))}
   143	      </div>
   144	      <DirectionToggle
   145	        onSelect={(direction) => onSortChange({ sortKey, direction })}
   146	        sortDirection={sortDirection}
   147	        sortKey={sortKey}
   148	      />
   149	    </SearchDropdown>
   150	  );
   151	};
