     1	import { App } from "obsidian";
     2	import { useEffect, useMemo, useRef, useState, type ReactElement } from "react";
     3	import { SearchDropdown } from "~/components/SearchDropdown";
     4	import { DiscourseNode } from "~/types";
     5	import { getAllDiscourseNodeColors } from "~/utils/colorUtils";
     6	import {
     7	  NODE_TYPE_FILTER_SEARCH_THRESHOLD,
     8	  filterNodeTypesByQuery,
     9	  fromPanelSelectedIds,
    10	  hasActiveTypeFilter,
    11	  toPanelSelectedIds,
    12	} from "~/utils/discourseNodeTypeFilter";
    13	
    14	const NodeTypeFilterRow = ({
    15	  color,
    16	  isChecked,
    17	  nodeType,
    18	  onSelectOnly,
    19	  onToggle,
    20	}: {
    21	  color: string | undefined;
    22	  isChecked: boolean;
    23	  nodeType: DiscourseNode;
    24	  onSelectOnly: () => void;
    25	  onToggle: () => void;
    26	}): ReactElement => (
    27	  <div className="hover:bg-modifier-hover group flex items-center gap-2 px-3 py-1.5">
    28	    <label className="flex min-w-0 flex-1 cursor-pointer items-center gap-2">
    29	      <input
    30	        type="checkbox"
    31	        checked={isChecked}
    32	        onChange={onToggle}
    33	        className="shrink-0"
    34	      />
    35	      {color && (
    36	        <span
    37	          style={{ backgroundColor: color }}
    38	          className="h-3 w-3 shrink-0 rounded-full"
    39	        />
    40	      )}
    41	      <span className="text-normal truncate text-sm">{nodeType.name}</span>
    42	    </label>
    43	    <button
    44	      type="button"
    45	      // Hidden until the row is hovered or focused so the list stays scannable,
    46	      // but focusable by keyboard rather than pointer-only.
    47	      className="text-muted hover:text-normal shrink-0 opacity-0 transition-opacity group-focus-within:opacity-100 group-hover:opacity-100"
    48	      onClick={(event) => {
    49	        event.stopPropagation();
    50	        onSelectOnly();
    51	      }}
    52	      onMouseDown={(event) => event.preventDefault()}
    53	    >
    54	      Only
    55	    </button>
    56	  </div>
    57	);
    58	
    59	const NodeTypeFilterPanel = ({
    60	  isFilterActive,
    61	  nodeTypes,
    62	  onSelectedIdsChange,
    63	  selectedIds,
    64	}: {
    65	  isFilterActive: boolean;
    66	  nodeTypes: DiscourseNode[];
    67	  onSelectedIdsChange: (ids: string[]) => void;
    68	  selectedIds: string[];
    69	}): ReactElement => {
    70	  const [query, setQuery] = useState("");
    71	  const searchRef = useRef<HTMLInputElement | null>(null);
    72	
    73	  const showTypeSearch = nodeTypes.length > NODE_TYPE_FILTER_SEARCH_THRESHOLD;
    74	
    75	  const colorsById = useMemo(() => {
    76	    const byId = new Map<string, string>();
    77	    getAllDiscourseNodeColors(nodeTypes).forEach(({ nodeType, colors }) => {
    78	      byId.set(nodeType.id, colors.backgroundColor);
    79	    });
    80	    return byId;
    81	  }, [nodeTypes]);
    82	
    83	  const filteredNodeTypes = useMemo(
    84	    () => filterNodeTypesByQuery(nodeTypes, query),
    85	    [nodeTypes, query],
    86	  );
    87	
    88	  const selectedIdSet = useMemo(() => new Set(selectedIds), [selectedIds]);
    89	
    90	  useEffect(() => {
    91	    if (showTypeSearch) searchRef.current?.focus();
    92	  }, [showTypeSearch]);
    93	
    94	  const toggleType = (id: string): void => {
    95	    onSelectedIdsChange(
    96	      selectedIdSet.has(id)
    97	        ? selectedIds.filter((selectedId) => selectedId !== id)
    98	        : [...selectedIds, id],
    99	    );
   100	  };
   101	
   102	  return (
   103	    <>
   104	      {/* Clearing is the only thing this control ever does, so it says so and
   105	          appears only when there is a filter to clear. A "select all" checkbox
   106	          would sit checked-and-inert whenever no filter is active, since an empty
   107	          selection and a full one are the same state. */}
   108	      {isFilterActive && (
   109	        <div className="border-modifier-border border-b p-2">
   110	          <button
   111	            type="button"
   112	            onClick={() => onSelectedIdsChange([])}
   113	            onMouseDown={(event) => event.preventDefault()}
   114	            className="w-full text-sm"
   115	          >
   116	            {`Clear filter (${selectedIds.length})`}
   117	          </button>
   118	        </div>
   119	      )}
   120	      {showTypeSearch && (
   121	        <div className="border-modifier-border border-b p-2">
   122	          <input
   123	            ref={searchRef}
   124	            type="text"
   125	            value={query}
   126	            placeholder="Filter types…"
   127	            onChange={(event) => setQuery(event.target.value)}
   128	            className="w-full"
   129	          />
   130	        </div>
   131	      )}
   132	      <div className="max-h-64 overflow-y-auto py-1">
   133	        {filteredNodeTypes.length === 0 ? (
   134	          <div className="text-muted p-4 text-center text-sm">
   135	            No matching node types
   136	          </div>
   137	        ) : (
   138	          filteredNodeTypes.map((nodeType) => (
   139	            <NodeTypeFilterRow
   140	              key={nodeType.id}
   141	              color={colorsById.get(nodeType.id)}
