import { App } from "obsidian";
import { useEffect, useMemo, useRef, useState, type ReactElement } from "react";
import { SearchDropdown } from "~/components/SearchDropdown";
import { DiscourseNode } from "~/types";
import { getAllDiscourseNodeColors } from "~/utils/colorUtils";
import {
  NODE_TYPE_FILTER_SEARCH_THRESHOLD,
  filterNodeTypesByQuery,
  fromPanelSelectedIds,
  hasActiveTypeFilter,
  toPanelSelectedIds,
} from "~/utils/discourseNodeTypeFilter";

const NodeTypeFilterRow = ({
  color,
  isChecked,
  nodeType,
  onSelectOnly,
  onToggle,
}: {
  color: string | undefined;
  isChecked: boolean;
  nodeType: DiscourseNode;
  onSelectOnly: () => void;
  onToggle: () => void;
}): ReactElement => (
  <div className="hover:bg-modifier-hover group flex items-center gap-2 px-3 py-1.5">
    <label className="flex min-w-0 flex-1 cursor-pointer items-center gap-2">
      <input
        type="checkbox"
        checked={isChecked}
        onChange={onToggle}
        className="shrink-0"
      />
      {color && (
        <span
          style={{ backgroundColor: color }}
          className="h-3 w-3 shrink-0 rounded-full"
        />
      )}
      <span className="text-normal truncate text-sm">{nodeType.name}</span>
    </label>
    <button
      type="button"
      // Pointer-only: arrow keys stop once per row, on the checkbox.
      tabIndex={-1}
      // Hidden until the row is hovered or focused so the list stays scannable.
      className="text-muted hover:text-normal shrink-0 opacity-0 transition-opacity group-focus-within:opacity-100 group-hover:opacity-100"
      onClick={(event) => {
        event.stopPropagation();
        onSelectOnly();
      }}
      onMouseDown={(event) => event.preventDefault()}
    >
      Only
    </button>
  </div>
);

const NodeTypeFilterPanel = ({
  isFilterActive,
  nodeTypes,
  onSelectedIdsChange,
  selectedIds,
}: {
  isFilterActive: boolean;
  nodeTypes: DiscourseNode[];
  onSelectedIdsChange: (ids: string[]) => void;
  selectedIds: string[];
}): ReactElement => {
  const [query, setQuery] = useState("");
  const searchRef = useRef<HTMLInputElement | null>(null);

  const showTypeSearch = nodeTypes.length > NODE_TYPE_FILTER_SEARCH_THRESHOLD;

  const colorsById = useMemo(() => {
    const byId = new Map<string, string>();
    getAllDiscourseNodeColors(nodeTypes).forEach(({ nodeType, colors }) => {
      byId.set(nodeType.id, colors.backgroundColor);
    });
    return byId;
  }, [nodeTypes]);

  const filteredNodeTypes = useMemo(
    () => filterNodeTypesByQuery(nodeTypes, query),
    [nodeTypes, query],
  );

  const selectedIdSet = useMemo(() => new Set(selectedIds), [selectedIds]);

  useEffect(() => {
    if (showTypeSearch) searchRef.current?.focus();
  }, [showTypeSearch]);

  const toggleType = (id: string): void => {
    onSelectedIdsChange(
      selectedIdSet.has(id)
        ? selectedIds.filter((selectedId) => selectedId !== id)
        : [...selectedIds, id],
    );
  };

  return (
    <>
      {/* Clearing is the only thing this control ever does, so it says so and
          appears only when there is a filter to clear. A "select all" checkbox
          would sit checked-and-inert whenever no filter is active, since an empty
          selection and a full one are the same state. */}
      {isFilterActive && (
        <div className="border-modifier-border border-b p-2">
          <button
            type="button"
            onClick={() => onSelectedIdsChange([])}
            onMouseDown={(event) => event.preventDefault()}
            className="w-full text-sm"
          >
            {`Clear filter (${selectedIds.length})`}
          </button>
        </div>
      )}
      {showTypeSearch && (
        <div className="border-modifier-border border-b p-2">
          <input
            ref={searchRef}
            type="text"
            value={query}
            placeholder="Filter types…"
            onChange={(event) => setQuery(event.target.value)}
            className="w-full"
          />
        </div>
      )}
      <div className="max-h-64 overflow-y-auto py-1">
        {filteredNodeTypes.length === 0 ? (
          <div className="text-muted p-4 text-center text-sm">
            No matching node types
          </div>
        ) : (
          filteredNodeTypes.map((nodeType) => (
            <NodeTypeFilterRow
              key={nodeType.id}
              color={colorsById.get(nodeType.id)}
              isChecked={selectedIdSet.has(nodeType.id)}
              nodeType={nodeType}
              onSelectOnly={() => onSelectedIdsChange([nodeType.id])}
              onToggle={() => toggleType(nodeType.id)}
            />
          ))
        )}
      </div>
    </>
  );
};

export const NodeTypeFilterMenu = ({
  app,
  isOpen,
  nodeTypes,
  onOpenChange,
  onSelectedNodeTypeIdsChange,
  selectedNodeTypeIds,
}: {
  app: App;
  isOpen: boolean;
  nodeTypes: DiscourseNode[];
  onOpenChange: (isOpen: boolean) => void;
  onSelectedNodeTypeIdsChange: (ids: string[]) => void;
  selectedNodeTypeIds: string[];
}): ReactElement => {
  const allTypeIds = useMemo(
    () => nodeTypes.map((nodeType) => nodeType.id),
    [nodeTypes],
  );

  const isFilterActive = hasActiveTypeFilter({
    selectedTypeIds: selectedNodeTypeIds,
    allTypeIds,
  });

  const panelSelectedIds = useMemo(
    () =>
      toPanelSelectedIds({ selectedTypeIds: selectedNodeTypeIds, allTypeIds }),
    [allTypeIds, selectedNodeTypeIds],
  );

  const activeFilterCount = isFilterActive ? selectedNodeTypeIds.length : 0;

  return (
    <SearchDropdown
      app={app}
      ariaLabel={
        activeFilterCount > 0
          ? `Filter by type, ${activeFilterCount} selected`
          : "Filter by type"
      }
      badgeCount={activeFilterCount}
      iconName="filter"
      isActive={isFilterActive}
      isDisabled={nodeTypes.length === 0}
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      panelClassName="w-64"
      title={
        nodeTypes.length === 0
          ? "No discourse node types configured"
          : "Filter by type"
      }
    >
      <NodeTypeFilterPanel
        isFilterActive={isFilterActive}
        nodeTypes={nodeTypes}
        onSelectedIdsChange={(panelIds) =>
          onSelectedNodeTypeIdsChange(
            fromPanelSelectedIds({ panelSelectedIds: panelIds, allTypeIds }),
          )
        }
        selectedIds={panelSelectedIds}
      />
    </SearchDropdown>
  );
};

import { App, Scope, setIcon } from "obsidian";
import {
  useEffect,
  useRef,
  type KeyboardEvent,
  type ReactElement,
  type ReactNode,
} from "react";

/** Which toolbar panel is open, so two can never be open at once. */
export type SearchDropdownId =
  | "type-filter"
  | "sort"
  | "display-options"
  | null;

/** Keyboard-only ring for div items; inset so the panel's overflow-hidden can't clip it. */
export const SEARCH_DROPDOWN_ITEM_FOCUS_RING =
  "outline-none focus-visible:[box-shadow:inset_0_0_0_2px_var(--background-modifier-border-focus)]";

// tabIndex -1 opts an item out of arrow navigation.
const FOCUSABLE_SELECTOR =
  ':is(input, button, [tabindex]):not([disabled], [tabindex="-1"])';

const getFocusableItems = (panel: HTMLElement): HTMLElement[] =>
  Array.from(panel.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR));

export const SearchDropdown = ({
  app,
  ariaLabel,
  badgeCount = 0,
  children,
  iconName,
  isActive,
  isDisabled = false,
  isOpen,
  onOpenChange,
  panelClassName = "w-64",
  title,
}: {
  app: App;
  ariaLabel: string;
  badgeCount?: number;
  children: ReactNode;
  iconName: string;
  isActive: boolean;
  isDisabled?: boolean;
  isOpen: boolean;
  onOpenChange: (isOpen: boolean) => void;
  panelClassName?: string;
  title: string;
}): ReactElement => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const panelRef = useRef<HTMLDivElement | null>(null);
  const isKeyboardOpenRef = useRef(false);

  // Runs after the panel's own effects, so a panel that focuses something itself keeps it.
  useEffect(() => {
    const panel = panelRef.current;
    if (!isOpen || !panel || panel.contains(activeDocument.activeElement)) {
      return;
    }
    // Chromium rings any item focused from a text input, so a pointer open parks focus on the panel instead.
    if (!isKeyboardOpenRef.current) {
      panel.focus();
      return;
    }
    (
      panel.querySelector<HTMLElement>('[aria-checked="true"]') ??
      getFocusableItems(panel)[0]
    )?.focus();
  }, [isOpen]);

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>): void => {
    if (!isOpen) return;
    // Panel keystrokes must not reach the modal's Enter and arrow result navigation; Escape never arrives here at all.
    event.stopPropagation();
    if (event.nativeEvent.isComposing) return;

    if (event.key === "Tab") {
      // Tab only closes; focus returns to the trigger instead of moving on.
      event.preventDefault();
      onOpenChange(false);
      triggerRef.current?.focus();
      return;
    }

    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
    const items = panelRef.current ? getFocusableItems(panelRef.current) : [];
    if (!items.length) return;
    event.preventDefault();
    const delta = event.key === "ArrowDown" ? 1 : -1;
    const index = items.indexOf(activeDocument.activeElement as HTMLElement);
    const next =
      index === -1
        ? delta === 1
          ? 0
          : items.length - 1
        : (index + delta + items.length) % items.length;
    items[next]?.focus();
  };

  // Obsidian's modal Escape is registered before React exists, and wins on its own scope too, so only a pushed scope gets it first.
  useEffect(() => {
    if (!isOpen) return;
    const scope = new Scope();
    scope.register([], "Escape", () => {
      onOpenChange(false);
      return false;
    });
    app.keymap.pushScope(scope);
    return () => app.keymap.popScope(scope);
  }, [app, isOpen, onOpenChange]);

  // `activeDocument`, so the listener lands in the popout window holding the modal.
  useEffect(() => {
    if (!isOpen) return;
    const handlePointerDown = (event: MouseEvent) => {
      if (containerRef.current?.contains(event.target as Node)) return;
      onOpenChange(false);
    };
    activeDocument.addEventListener("mousedown", handlePointerDown, true);
    return () =>
      activeDocument.removeEventListener("mousedown", handlePointerDown, true);
  }, [isOpen, onOpenChange]);

  return (
    <div
      ref={containerRef}
      className="relative shrink-0"
      onKeyDown={handleKeyDown}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-expanded={isOpen}
        aria-label={ariaLabel}
        disabled={isDisabled}
        title={title}
        onClick={(event) => {
          // `detail` is 0 when Enter or Space activated the button.
          isKeyboardOpenRef.current = event.detail === 0;
          onOpenChange(!isOpen);
        }}
        // Keeps focus in the search input, so arrow and Enter navigation stays live.
        onMouseDown={(event) => event.preventDefault()}
        className={`clickable-icon relative ${isOpen || isActive ? "is-active" : ""}`}
      >
        <span
          className="flex items-center"
          ref={(el) => (el && setIcon(el, iconName)) || undefined}
        />
        {badgeCount > 0 && (
          <span
            aria-hidden
            className="bg-accent text-on-accent pointer-events-none absolute -right-1 -top-1 flex h-3.5 min-w-3.5 items-center justify-center rounded-lg px-1 text-xs font-semibold leading-none"
          >
            {badgeCount}
          </span>
        )}
      </button>
      {isOpen && (
        <div
          ref={panelRef}
          tabIndex={-1}
          className={`border-modifier-border absolute right-0 top-full z-50 mt-1 overflow-hidden rounded-md border bg-primary shadow-[shadow:var(--shadow-s)] outline-none ${panelClassName}`}
        >
          {children}
        </div>
      )}
    </div>
  );
};

